		/** 
		 * Tests creating a new Endorsement.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Endorsement");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Endorsement" );

			try {            
				Endorsement entity = EndorsementService.getEndorsementInstance().createEndorsement( generateNewEntity() );
				thePrimaryKey = entity.getEndorsementId();
				LOGGER.info( "-- Successfully created a Endorsement with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Endorsement. 
		 */
		public Endorsement testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Endorsement" );

			Endorsement entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Endorsement with primary key" );
			msg.append( thePrimaryKey );
			
			EndorsementFetchOneSummary fetchOneSummary = new EndorsementFetchOneSummary( thePrimaryKey );

			try {
				entity = EndorsementService.getEndorsementInstance().getEndorsement( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Endorsement " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Endorsement.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Endorsement." );

			StringBuilder msg = new StringBuilder( "Failed to update a Endorsement : " );        
			Endorsement entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Endorsement." );

				// for use later on...
				thePrimaryKey = entity.getEndorsementId();

				EndorsementService proxy = EndorsementService.getEndorsementInstance();            
				proxy.updateEndorsement( entity );   

				LOGGER.info( "-- Successfully saved Endorsement - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Endorsement.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Endorsement." );

			try{
			    Endorsement entity = testRead(); 
				EndorsementService.getEndorsementInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Endorsement with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Endorsement with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Endorsements.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Endorsements:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Endorsement : " );        
			List<Endorsement> collection  = null;

			try {
				// call the static get method on the EndorsementService
				collection = EndorsementService.getEndorsementInstance().getAllEndorsement();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Endorsement entity = null;            
					Iterator<Endorsement> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getEndorsementId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

